body.raw:
{
  "name": "SecureTestBrand_{{timestamp}}",
  "description": "Test brand for secure contracts with enhanced security features",
  "website": "https://securetestbrand.com",
  "authorizedCountries": ["US", "CA", "GB", "DE", "FR"],
  "ipfsData": {
    "metadata": {
      "name": "Secure Test Brand Registration",
      "description": "Brand registration for secure contract testing",
      "image": "https://via.placeholder.com/400x400?text=SecureTestBrand",
      "attributes": [
        {
          "trait_type": "Security Level",
          "value": "Enhanced"
        },
        {
          "trait_type": "Contract Version",
          "value": "Secure v3.0"
        },
        {
          "trait_type": "Registration Date",
          "value": "{{$timestamp}}"
        }
      ]
    }
  }
}

{
  "isActive": true,
  "reason": "Brand activation for testing secure contracts"
}

{
  "brandId": "{{testBrandId}}",
  "productName": "Secure Test Product {{timestamp}}",
  "productDescription": "High-security test product with enhanced blockchain verification",
  "serialNumber": "SEC{{timestamp}}",
  "manufacturingDate": {{$timestamp}},
  "expiryDate": {{$timestamp}} + 31536000,
  "ipfsData": {
    "metadata": {
      "name": "Secure Product Passport",
      "description": "Product passport for secure contract testing with enhanced features",
      "image": "https://via.placeholder.com/400x400?text=SecureProduct",
      "attributes": [
        {
          "trait_type": "Security Level",
          "value": "Maximum"
        },
        {
          "trait_type": "Contract Version",
          "value": "Secure v3.0"
        },
        {
          "trait_type": "Manufacturing Location",
          "value": "Secure Facility A"
        },
        {
          "trait_type": "Quality Grade",
          "value": "Premium"
        }
      ]
    }
  }
}

{
  "passportId": {{testPassportId}},
  "entryType": "MANUFACTURING",
  "location": "Secure Manufacturing Facility - Building A",
  "description": "Product manufactured under enhanced security protocols with blockchain verification",
  "ipfsData": {
    "metadata": {
      "name": "Secure Manufacturing Entry",
      "description": "Manufacturing provenance entry with enhanced security tracking",
      "attributes": [
        {
          "trait_type": "Entry Type",
          "value": "Manufacturing"
        },
        {
          "trait_type": "Security Level",
          "value": "Maximum"
        },
        {
          "trait_type": "Facility ID",
          "value": "SEC-FAC-001"
        },
        {
          "trait_type": "Quality Control Passed",
          "value": "Yes"
        },
        {
          "trait_type": "Timestamp",
          "value": "{{$timestamp}}"
        }
      ]
    }
  }
}

{
  "passportId": {{testPassportId}},
  "entryType": "TRANSFER",
  "location": "Secure Distribution Center - Hub B",
  "description": "Product transferred to distribution center with full security tracking and verification",
  "ipfsData": {
    "metadata": {
      "name": "Secure Transfer Entry",
      "description": "Product transfer entry with enhanced chain of custody",
      "attributes": [
        {
          "trait_type": "Entry Type",
          "value": "Transfer"
        },
        {
          "trait_type": "Transfer From",
          "value": "Manufacturing Facility"
        },
        {
          "trait_type": "Transfer To",
          "value": "Distribution Center"
        },
        {
          "trait_type": "Security Verified",
          "value": "Yes"
        },
        {
          "trait_type": "Chain of Custody ID",
          "value": "COC-{{$timestamp}}"
        }
      ]
    }
  }
}

{
  "passportId": {{testPassportId}},
  "ownerAddress": "{{testAddress}}",
  "purchaseDate": {{$timestamp}},
  "purchasePrice": "2500000000000000000",
  "ipfsData": {
    "metadata": {
      "name": "Secure Ownership Deed",
      "description": "Digital ownership deed with enhanced blockchain security and verification",
      "attributes": [
        {
          "trait_type": "Ownership Type",
          "value": "Full Ownership"
        },
        {
          "trait_type": "Security Level",
          "value": "Maximum"
        },
        {
          "trait_type": "Verification Status",
          "value": "Blockchain Verified"
        },
        {
          "trait_type": "Purchase Price (ETH)",
          "value": "2.5"
        },
        {
          "trait_type": "Legal Jurisdiction",
          "value": "Digital Asset Laws"
        }
      ]
    }
  }
}

{
  "deedId": {{testDeedId}},
  "newOwnerAddress": "0x9876543210987654321098765432109876543210",
  "transferPrice": "3000000000000000000",
  "reason": "Secure ownership transfer with enhanced verification protocols"
}

{
  "eventName": "Secure Blockchain Conference {{timestamp}}",
  "eventDescription": "Premium blockchain conference featuring secure smart contracts and advanced DeFi protocols",
  "eventDate": {{$timestamp}} + 604800,
  "maxAttendees": 500,
  "ipfsData": {
    "metadata": {
      "name": "Secure Blockchain Conference",
      "description": "Elite conference for blockchain security professionals and developers",
      "image": "https://via.placeholder.com/600x400?text=SecureBlockchainConf",
      "attributes": [
        {
          "trait_type": "Event Type",
          "value": "Professional Conference"
        },
        {
          "trait_type": "Security Level",
          "value": "High"
        },
        {
          "trait_type": "Target Audience",
          "value": "Blockchain Professionals"
        },
        {
          "trait_type": "Venue Type",
          "value": "Premium Location"
        },
        {
          "trait_type": "Registration Required",
          "value": "Yes"
        }
      ]
    }
  }
}

{
  "eventId": {{testEventId}},
  "attendeeAddress": "{{testAddress}}",
  "additionalInfo": "Excited to attend this secure blockchain conference!"
}
